func validateInvocationInput(
	input InvocationInput,
	pathNames []string,
	queryNames []string,
	headerNames []string,
	bodyPresent bool,
	bodyRequired bool,
) error {
	if len(input.Path) != len(pathNames) {
		return &InvocationInputError{
			Location: "path",
			Name:     "values",
			Err:      fmt.Errorf("got %d values, want %d", len(input.Path), len(pathNames)),
		}
	}
	var unknownQueryNames []string
	for name := range input.Query {
		index := sort.SearchStrings(queryNames, name)
		if index == len(queryNames) || queryNames[index] != name {
			unknownQueryNames = append(unknownQueryNames, name)
		}
	}
	if len(unknownQueryNames) > 0 {
		sort.Strings(unknownQueryNames)
		return &InvocationInputError{
			Location: "query",
			Name:     unknownQueryNames[0],
			Err:      errors.New("parameter is not declared by the operation"),
		}
	}
	var unknownHeaderNames []string
	for name := range input.Header {
		index := sort.SearchStrings(headerNames, name)
		if index == len(headerNames) || headerNames[index] != name {
			unknownHeaderNames = append(unknownHeaderNames, name)
		}
	}
	if len(unknownHeaderNames) > 0 {
		sort.Strings(unknownHeaderNames)
		return &InvocationInputError{
			Location: "header",
			Name:     unknownHeaderNames[0],
			Err:      errors.New("parameter is not declared by the operation"),
		}
	}
	if !bodyPresent && input.Body != nil {
		return &InvocationInputError{
			Location: "body",
			Name:     "body",
			Err:      errors.New("operation does not accept a request body"),
		}
	}
	if bodyRequired && input.Body == nil {
		return &InvocationInputError{
			Location: "body",
			Name:     "body",
			Err:      errors.New("value is required"),
		}
	}
	return nil
}

func parseInvocationValue(raw string, stringValue bool, target any) error {
	encoded := []byte(raw)
	if stringValue {
		encoded, _ = json.Marshal(raw)
	}
	return json.Unmarshal(encoded, target)
}

func normalizeInvocationResult(body []byte, response *http.Response) (InvocationResult, error) {
	if response == nil {
		return InvocationResult{}, errors.New("generated client returned no HTTP response")
	}
	return InvocationResult{
		StatusCode: response.StatusCode,
		Headers:    map[string][]string(response.Header.Clone()),
		Body:       body,
	}, nil
}

